            if (ImGui::IsItemHovered()) ImGui::SetTooltip("Hold to run (blank = disabled)");
            if (ImGui::DragFloat("Acceleration##cc2", &cc->acceleration, 0.5f, 0.0f, 500.0f)) ed.dirty = true;
