            if (ImGui::DragFloat("Points##co", &co->points, 0.1f, -100000.0f, 100000.0f)) ed.dirty = true;
            if (ImGui::DragFloat("Heal##co", &co->heal, 0.5f, 0.0f, 100000.0f)) ed.dirty = true;
